import sys

class Car:
    def __init__(self, brand, model):
        self.brand = brand
        self.model = model

    def park_to_garage(self, garage):
        garage.parkCar(self)

class Garage:
    def __init__(self):
        self.slots = {}
        self.next_slot = 1

    def parkCar(self, car):
        self.slots[self.next_slot] = car
        print(f"Car {car.brand} {car.model} has been parked in slot #{self.next_slot}")
        self.next_slot += 1

    def display_status(self):
        print("--- Garage Status ---")
        for slot_num, car in self.slots.items():
            print(f"Slot {slot_num}: {car.brand} {car.model}")

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    n = int(data[0])

    garage = Garage()

    for i in range(n):
        if i * 2 + 1 < len(data):
            brand = data[i * 2 + 1]
            model = data[i * 2 + 2] if i * 2 + 2 < len(data) else ""
            car = Car(brand, model)
            car.park_to_garage(garage)

    garage.display_status()

if __name__ == "__main__":
    main()
